package com.kavi.kavimart.dao;
import com.kavi.kavimart.dto.OrderSummaryDTO;import java.util.List;import java.util.Optional;
/** Persistence contract for transactional orders and order status changes. */
public interface OrderDao { /** Place a buyer's cart as one atomic checkout transaction. */ OrderSummaryDTO placeOrder(long buyerId); /** Find a complete order by id. */ Optional<OrderSummaryDTO> findById(long id); /** List one buyer's order history. */ List<OrderSummaryDTO> findByBuyer(long buyerId); /** List orders with products belonging to a seller. */ List<OrderSummaryDTO> findBySeller(long sellerId); /** List all orders for administration. */ List<OrderSummaryDTO> findAll(); /** Advance a seller's order with an expected previous status. */ boolean transitionSeller(long orderId,long sellerId,String expected,String next); /** Cancel a pending buyer order and restore stock atomically. */ boolean cancelPending(long orderId,long buyerId); /** Return the number of orders and revenue for seller listings. */ java.util.Map<String,java.math.BigDecimal> sellerStats(long sellerId); }
